using System;using System.IO;using System.Linq;using Game.Configs;using Newtonsoft.Json.Linq;
namespace Game.Runtime{internal static class SourceDeclaredMissionLogicalBindingReference{
 static JObject Read(JObject descriptor,JObject request){if(descriptor==null||descriptor.Count!=2||descriptor["path"]?.Type!=JTokenType.String||descriptor["sha256"]?.Type!=JTokenType.String)throw new InvalidDataException("Explicit declared logical binding descriptor required");var root=JObject.Parse(System.Text.Encoding.UTF8.GetString(AutonomousWorld.PinnedFile((string)descriptor["path"],(string)descriptor["sha256"],4*1024*1024)),new JsonLoadSettings{DuplicatePropertyNameHandling=DuplicatePropertyNameHandling.Error});if(root["schema_version"]?.Type!=JTokenType.Integer||(int)root["schema_version"]!=1||(string)root["kind"]!="OriginalCompilerDeclaredLogicalBinding"||!JToken.DeepEquals(root["metadata_compiler_context"],request["metadata_compiler_context"])||(bool?)root["native_capture"]!=false||(bool?)root["source_fit_certified"]!=false||(bool?)root["mission_ready"]!=false)throw new InvalidDataException("Honest declared configuration reference required");var context=SourceDeclaredMissionConfiguration.Context(request);if(!JToken.DeepEquals(root["target_context"],context["target_context"]))throw new InvalidDataException("Declared binding target differs from qualified compiler context");return root;}
 internal static JObject Bind(JObject descriptor,SkirmishScenarioDefinitionConfig definition,JObject request){var root=Read(descriptor,request);var p=root["portable_binding"]as JObject;if(p==null||(string)p["kind"]!="DeclaredOriginalLogicalBindingFieldsWithInlineViews"||(string)p["float_encoding"]!="IEEE754_float32_hex_bits"||(bool?)p["unity_object_ids_exported"]!=false)throw new InvalidDataException("Original raw-bit logical value codec required");var binding=SourceNativeMissionLogicalBindingReference.DecodeDeclaredFields(p["fields"]);if(definition==null||definition.MissionLogicalBinding!=null||binding.CatalogId!=definition.CatalogId||binding.DefinitionId!=definition.DefinitionId||binding.DefinitionVersion!=definition.ContentVersion||binding.ValueFormat!=definition.MapLayout.BindingValueFormat||binding.Variants==null)throw new InvalidDataException("Fresh canonical BA logical binding required");RequireVariants(binding,definition,SourceDeclaredMissionConfiguration.Context(request));definition.BindMissionLogicalBinding(binding);return root;}
 internal static void RequireVariants(SkirmishMissionLogicalBindingConfig binding,SkirmishScenarioDefinitionConfig definition,JObject context){bool all=SourceDeclaredMissionConfiguration.RequireLayoutSelection(definition.MapLayout,context);var variants=binding.Variants;if(variants.Any(v=>v==null||v.Areas!=null))throw new InvalidDataException("Complete BA logical variants required");var target=context["target_context"];if(variants.Count(v=>v.Size.ToString()==(string)target["size"]&&v.Difficulty.ToString()==(string)target["difficulty"])!=1)throw new InvalidDataException("One exact selected logical variant required");if(!all&&variants.Length!=1)throw new InvalidDataException("Single declared layout requires one variant");if(all&&(variants.Length!=3||variants.Any(v=>v.Difficulty.ToString()!="Regular")||variants.Select(v=>v.Size.ToString()).Distinct().Count()!=3||!new[]{"Standard","War","LargeWar"}.All(size=>variants.Any(v=>v.Size.ToString()==size))))throw new InvalidDataException("Measured all-configuration layout requires exact three Regular size variants");}
 internal static void RequireCompiled(JObject descriptor,SkirmishScenarioDefinitionConfig definition,SkirmishResolvedSetup setup,JObject request){var root=Read(descriptor,request);var target=root["target_context"];string error=null;if((uint?)target["setup_hash"]!=setup.SetupHash||(int?)target["seed"]!=setup.Seed||(string)target["catalog_id"]!=setup.CatalogId||!SkirmishMissionLogicalBindingCompiler.TryCompile(definition,setup,out var logical,out error)||logical.Fingerprint!=setup.MissionLogicalBindingFingerprint||logical.Fingerprint!=(string)target["mission_logical_binding_fingerprint"])throw new InvalidDataException("Actual original declared logical compiler differs: "+error);}
}}
